+    part.lastIndex = pos;
+    const m = part.exec(s);
+    if (!m) throw new Error(`invalid duration: ${JSON.stringify(text)}`);
+    total += parseFloat(m[1]) * UNIT_MS[m[2]];
+    pos = part.lastIndex;
+  }
